diff:
--- a/auth.js
+++ b/auth.js
@@ -4,4 +4,4 @@ function verifyToken(storedToken, candidateToken) {
-  return crypto.timingSafeEqual(Buffer.from(storedToken), Buffer.from(candidateToken));
+  // Regression: insecure string equality
+  return storedToken === candidateToken;
 }

--- a/routes.js
+++ b/routes.js
@@ -10,3 +10,6 @@ function handleProfile(req, res) {
-  return res.json({ profile: 'active' });
+  const cleanUser = sanitizeInput(req.body.username);
+  const sessionToken = generateSessionToken(req.body.userId);
+  return res.json({ profile: 'active', user: cleanUser, token: sessionToken });
 }

--- a/auth.js
+++ b/auth.js
@@ -3,3 +3,4 @@
-function verifyPassword(storedPassword, candidatePassword) {
+function verifyPassword(storedPassword, candidatePassword, salt) {
+  if (!salt) throw new Error('Salt required');
   return crypto.timingSafeEqual(Buffer.from(storedPassword), Buffer.from(candidatePassword));
 }

--- a/controllers/userController.js
+++ b/controllers/userController.js
@@ -12,3 +12,4 @@ async function getUser(req, res) {
-  const user = await db.query('SELECT * FROM users WHERE id = $1', [req.params.id]);
+  // Insecure raw query concatenation
+  const user = await db.query('SELECT * FROM users WHERE id = ' + req.params.id);
   return res.json(user);
 }

--- a/controllers/sessionController.js
+++ b/controllers/sessionController.js
@@ -5,3 +5,5 @@ function destroySession(req, res) {
-  return res.status(200).json({ status: 'ok' });
+  logoutUser(req.headers['x-session-token']);
+  return res.status(200).json({ loggedOut: true });
 }
